WAYBARCONF

	# Transparency presets. The bar is one material: the panel and the pills
	# share a level so the whole strip looks consistent over the wallpaper.
	local bar_bg pill_bg
	case "${BAR_OPACITY:-solid}" in
	soft)
		bar_bg="rgba(23,27,28,0.82)"
		pill_bg="rgba(47,51,54,0.72)"
		;;
	clear)
		bar_bg="rgba(23,27,28,0.55)"
		pill_bg="rgba(47,51,54,0.45)"
		;;
	*)
		bar_bg="#171b1c"
		pill_bg="#2f3336"
		;;
	esac
	local css_tmp; css_tmp="$(mktemp)"
	sed -e "s|__BAR_BG__|${bar_bg}|g" \
		-e "s|__PILL_BG__|${pill_bg}|g" >"${css_tmp}" <<'WAYBARCSS'
/* Waybar - Everforest rice (1:1 with the original screenshot)
 *
 * Geometry measured from the reference screenshot (1920x1080):
 *   bar height 40px, pills 30px tall, 8px gaps, 12px side padding,
 *   pill radius 10px, workspace pill 50px wide when active.
 * Palette: bar #171b1c, pill #2f3336, text #d3c6aa, cream #fffbef,
 *          lime #b9ff66, green #3ae93a, violet #8b93e3, red #d95d55.
 */

* {
  font-family: "JetBrains Mono", "Symbols Nerd Font", "Font Awesome 6 Free", sans-serif;
  font-size: 14px;
  font-weight: 700;
  min-height: 0;
  border: none;
  border-radius: 0;
}

/* Floating bar: it does not touch the screen edges, and the panel itself is
 * rounded like the reference. The window is transparent so the rounded
 * corners are real rather than painted over the wallpaper. */
window#waybar {
  background-color: transparent;
  color: #d3c6aa;
}

/* Transparency level, chosen at install time (see BAR_OPACITY):
 *   solid  #171b1c              - opaque
 *   soft   rgba(23,27,28,0.82)  - wallpaper just shows through
 *   clear  rgba(23,27,28,0.55)  - obvious see-through
 * Waybar is a GTK layer shell surface, so alpha is composited by sway; no
 * blur is involved because sway has no blur support. */
window#waybar > box {
  background-color: __BAR_BG__;
  border-radius: 12px;
}

/* Keep the three groups pinned to the edges like the reference. */
.modules-left {
  margin-left: 3px;
}
.modules-right {
  margin-right: 2px;
}

/* ---------------------------------------------------------------
 * Pills: every module is a dark rounded box on the bar.
 * --------------------------------------------------------------- */
#pulseaudio,
#custom-volume,
#custom-backlight,
#backlight,
#custom-colorpicker,
#custom-ime,
#custom-stats,
#custom-sysinfo,
#custom-temperatures,
#custom-launcher,
#custom-notifications,
#custom-power,
#clock,
#network,
#tray,
#custom-separator {
  background-color: __PILL_BG__;
  color: #d3c6aa;
  border-radius: 9px;
  padding: 0 11px;
  margin: 4px 4px;
  min-height: 0;
}

/* The reference keeps a uniform 8px gutter: 4px on each side of a pill. */

/* Workspaces: only the focused one is a lime pill, the rest are borderless
 * numbers sitting directly on the bar, exactly like the reference. */
#workspaces {
  background-color: transparent;
  padding: 0;
  margin-left: 0;
  margin-right: 4px;
}
#workspaces button {
  background-color: transparent;
  color: #ffffff;
  border-radius: 11px;
  padding: 0 12px;
  margin: 5px 2px;
  min-width: 28px;
  min-height: 23px;
  transition: none;
  box-shadow: none;
  text-shadow: none;
}
#workspaces button.focused,
#workspaces button.active {
  background-color: #b9ff66;
  color: #171b1c;
  font-weight: 800;
}
#workspaces button:hover {
  background-color: #2f3336;
  color: #fffbef;
}
#workspaces button.urgent {
  background-color: #e67e80;
  color: #171b1c;
}

/* Round icon buttons (picker, ime, launcher, notifications). */
#custom-ime,
#custom-launcher,
#custom-notifications {
  color: #ffffff;
  padding: 0 9px;
  min-width: 22px;
}

#custom-colorpicker {
  color: #ffffff;
  padding: 0 5px;
  min-width: 16px;
}

/* The tall divider between the volume group and the icon buttons. */
#custom-separator {
  background-color: transparent;
  color: #4a5250;
  padding: 0 2px;
  margin: 5px 2px;
  font-size: 16px;
  font-weight: 400;
}

#custom-volume {
  color: #ffffff;
  padding: 0 8px;
  font-weight: 700;
}

#custom-sysinfo {
  color: #ffffff;
  padding: 0 12px;
  font-weight: 700;
}

#custom-temperatures {
  color: #ffffff;
  padding: 0 12px;
  font-weight: 700;
}

#custom-backlight {
  color: #ffffff;
  padding: 0 22px;
  font-weight: 700;
}

#backlight {
  color: #fffbef;
  padding: 0 12px;
  font-weight: 700;
}

#custom-stats {
  color: #d3c6aa;
  padding: 0 14px;
  font-weight: 700;
}

#custom-launcher {
  background-color: #00ff00;
  color: #102410;
  padding: 0 13px;
