}

#tray {
  background-color: transparent;
  padding: 0;
  margin: 0;
}
#tray > .passive { -gtk-icon-effect: dim; }
#tray > .needs-attention { -gtk-icon-effect: highlight; }
WAYBARCSS
	install_user_file "${dir}/style.css" 644 <"${css_tmp}"
